-- The three hướng tu quests now differ from each other (kiếm: kills, thuật: Yêu Đan and herbs, đan: herbs and pills).
-- Seeding never overwrites rows (INSERT OR IGNORE), so the stored definitions are updated here; a test checks they match the seed.
-- Progress on a path quest taken under the old definition simply counts under the new one (collect objectives keep no counter).
UPDATE quests SET def = '{"id":"path_kiem","chain":"path","seq":1,"giver":"path_kiem","titleVi":"Thử kiếm","descVi":"Kiếm tu lấy chiến đấu làm gốc. Hãy ra Hắc Mộc Lâm hạ 30 con quái để chứng tỏ kiếm tâm, rồi quay lại nhận Kiếm Tu Lệnh.","enabled":true,"requires":null,"minRealm":1,"path":"kiem","objective":{"kind":"kill","count":30,"map":"forest"},"rewards":{"items":[{"item":"path_item_kiem","qty":1}]}}', updated_at = 0 WHERE id = 'path_kiem';
UPDATE quests SET def = '{"id":"path_thuat","chain":"path","seq":2,"giver":"path_thuat","titleVi":"Lễ vật Yêu Đan","descVi":"Thuật tu cần linh khí cô đọng để thi triển pháp thuật. Mang đến 4 Yêu Đan và 8 Linh Thảo, ta sẽ trao Thuật Tu Lệnh.","enabled":true,"requires":null,"minRealm":1,"path":"thuat","objective":{"kind":"collect","item":"yeu_dan","qty":4,"also":[{"item":"linh_thao","qty":8}]},"rewards":{"items":[{"item":"path_item_thuat","qty":1}]}}', updated_at = 0 WHERE id = 'path_thuat';
UPDATE quests SET def = '{"id":"path_dan","chain":"path","seq":3,"giver":"path_dan","titleVi":"Dược liệu và đan thuốc","descVi":"Đan tu khởi đầu từ dược liệu và đan cơ bản. Mang đến 30 Linh Thảo và 5 Hồi Huyết Đan, ta sẽ trao Đan Tu Lệnh.","enabled":true,"requires":null,"minRealm":1,"path":"dan","objective":{"kind":"collect","item":"linh_thao","qty":30,"also":[{"item":"hoi_huyet_dan","qty":5}]},"rewards":{"items":[{"item":"path_item_dan","qty":1}]}}', updated_at = 0 WHERE id = 'path_dan';
UPDATE config_versions SET version = version + 1, updated_at = 0 WHERE name = 'quests';
